      "label": "Automotive brake caliper casting lot",
      "machine_hours": 1,
      "revenue": 5
    },
    {
      "variable": "x2",
      "order": "M2",
      "label": "Aerospace titanium bracket machining",
      "machine_hours": 2,
      "revenue": 8
    },
